<div class="breadcrumbs"><a href="<?= $link('/organizations/'.$organization['id']) ?>"><?= $e($organization['name']) ?></a><span>/</span><?= $e(['asset'=>'Configurations','article'=>'Documents','contact'=>'Contacts','location'=>'Locations'][$type]) ?></div>
<div class="section-actions"><p class="muted"><?= $trash?'Archived documentation can be restored.':'Documentation visible to your account.' ?></p><?php if($canWrite): ?><div><a class="text-link" href="<?= $link('/organizations/'.$organization['id'].'/'.$type.'?trash='.($trash?'0':'1')) ?>"><?= $trash?'Active records':'Archived records' ?></a> <a class="button" href="<?= $link('/organizations/'.$organization['id'].'/'.$type.'/new') ?>">+ New <?= $e(['asset'=>'configuration','article'=>'document','contact'=>'contact','location'=>'location'][$type]) ?></a></div><?php endif; ?></div>
<div class="card table-card configuration-table"><?php if($type==='asset'): ?><div class="table-toolbar"><details class="column-settings" id="configuration-columns"><summary aria-label="Configure columns" title="Configure columns"><span aria-hidden="true">⚙︎</span></summary><div class="column-panel"><h2>Configure columns</h2><form method="post" action="<?= $link('/organizations/'.$organization['id'].'/asset/columns') ?>"><?= $csrf ?><p class="help">Choose the information shown in this organization's configuration list. Your selection is saved for your account.</p><div class="form-grid"><?php foreach($configurationTable['available'] as $key=>$label): ?><label class="checkbox"><input type="checkbox" name="columns[]" value="<?= $e($key) ?>" <?= in_array($key,$configurationTable['selected'],true)?'checked':'' ?>><?= $e($label) ?></label><?php endforeach; ?></div><button class="button secondary">Save columns</button></form></div></details></div><?php endif; ?>
<?php if(!$records): ?><div class="empty-state"><h2>No <?= $e(['asset'=>'configuration','article'=>'document','contact'=>'contact','location'=>'location'][$type]) ?> records yet</h2><p><?= $canWrite?'Add a record to start documenting this organization.':'No records are available to your account.' ?></p></div><?php else: ?><div class="table-scroll"><table><thead><tr><?php if($type==='asset'): foreach($configurationTable['selected'] as $column): ?><th><?= $e($configurationTable['available'][$column]) ?></th><?php endforeach; else: ?><th>Name</th><th>Category</th><th>Visibility</th><th>Updated (UTC)</th><?php endif; ?><?php if($trash): ?><th>Action</th><?php endif; ?></tr></thead><tbody><?php foreach($records as $r): ?><tr><?php if($type==='asset'): foreach($configurationTable['selected'] as $column): $cell=$configurationTable['cells'][$r['id']][$column]??''; ?><td><?php if(!$trash): ?><a href="<?= $link('/records/'.$r['id']) ?>"><?= $e($cell===''?'—':$cell) ?></a><?php else: ?><?= $e($cell===''?'—':$cell) ?><?php endif; ?></td><?php endforeach; else: ?><td><?php if(!$trash): ?><a href="<?= $link('/records/'.$r['id']) ?>"><?= $e($r['title']) ?></a><?php else: ?><?= $e($r['title']) ?><?php endif; ?></td><td><?= $e($r['category']?:'—') ?></td><td><span class="badge <?= $r['visibility']==='client'?'shared':'' ?>"><?= $r['visibility']==='internal'?'Internal only':'Client visible' ?></span></td><td><?= $e($r['updated_at']) ?></td><?php endif; ?><?php if($trash): ?><td><form method="post" action="<?= $link('/records/'.$r['id'].'/restore') ?>"><?= $csrf ?><button class="button small secondary">Restore</button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<div class="pagination"><?php if($page>1): ?><a href="<?= $link('/organizations/'.$organization['id'].'/'.$type.'?page='.($page-1).'&trash='.(int)$trash) ?>">← Previous</a><?php endif; ?><?php if(count($records)===50): ?><a href="<?= $link('/organizations/'.$organization['id'].'/'.$type.'?page='.($page+1).'&trash='.(int)$trash) ?>">Next →</a><?php endif; ?></div>
